        hh=g; g=f; f=e; e=_mm256_add_epi32(d,t1); d=c; c=b; b=a; a=_mm256_add_epi32(t1,t2);
    }
    // add to state: extract 4 lanes
    uint32_t ra[4],rb[4],rc[4],rd[4],re[4],rf[4],rg[4],rh[4];
    _mm256_storeu_si256((__m256i*)ra,a);
    _mm256_storeu_si256((__m256i*)rb,b);
    _mm256_storeu_si256((__m256i*)rc,c);
    _mm256_storeu_si256((__m256i*)rd,d);
    _mm256_storeu_si256((__m256i*)re,e);
    _mm256_storeu_si256((__m256i*)rf,f);
    _mm256_storeu_si256((__m256i*)rg,g);
    _mm256_storeu_si256((__m256i*)rh,hh);
    // h[0] += ra[0], h[1] += rb[0], ... but wait, each lane is a different block!
    // lane 0 = block 0, lane 1 = block 1, etc. But the state h is shared (sequential).
    // This is WRONG for sequential blocks!
    (void)ra;(void)rb;(void)rc;(void)rd;(void)re;(void)rf;(void)rg;(void)rh;
}

